165	  // clang-format off
166	  registry.insert<mlir::arith::ArithDialect,
167	                  mlir::func::FuncDialect,
168	                  mlir::TF::TensorFlowDialect,
169	                  mlir::shape::ShapeDialect,
170	                  mlir::tf_device::TensorFlowDeviceDialect,
171	                  mlir::tf_executor::TensorFlowExecutorDialect>();
172	  mlir::func::registerAllExtensions(registry);
173	  // clang-format on
174	}
175	
176	absl::Status MlirFunctionOptimizationPass::Run(
177	    const std::string& function_name, const DeviceSet& device_set,
178	    const ConfigProto& config_proto,
179	    const FunctionOptimizationPass::FunctionOptions& function_options,
180	    std::unique_ptr<Graph>* graph, FunctionLibraryDefinition* flib_def,
181	    std::vector<std::string>* control_ret_node_names,
182	    bool* control_rets_updated) {
183	  //  overall_state equals to:
184	  //    Enabled if at least one pass is Enabled.
185	  //    Disabled if all passes are Disabled.
186	  //    FallbackEnabled if there are no Enabled passes and there is at least one
187	  //      FallbackEnabled pass.
188	  MlirOptimizationPassState overall_state = MlirOptimizationPassState::Disabled;
189	
190	  // Cache per pass state and reuse it during pass execution.
191	  std::vector<MlirOptimizationPassState> per_pass_state;
192	  per_pass_state.reserve(registry_->passes().size());
193	
194	  int num_passes_enabled = 0, num_passes_disabled = 0,
195	      num_passes_fallback_enabled = 0;
196	  for (const auto& pass_registration : registry_->passes()) {
197	    MlirOptimizationPassState pass_state = pass_registration.pass->GetPassState(
198	        &device_set, config_proto, **graph, *flib_def);
199	    per_pass_state.push_back(pass_state);
200	    switch (pass_state) {
201	      case MlirOptimizationPassState::FallbackEnabled: {
202	        if (overall_state != MlirOptimizationPassState::Enabled)
203	          overall_state = MlirOptimizationPassState::FallbackEnabled;
204	        ++num_passes_fallback_enabled;
205	        break;
206	      }
207	      case MlirOptimizationPassState::Enabled: {
208	        overall_state = MlirOptimizationPassState::Enabled;
209	        ++num_passes_enabled;
210	        break;
211	      }
212	      case MlirOptimizationPassState::Disabled: {
213	        ++num_passes_disabled;
214	        break;
215	      }
216	    }
217	  }
218	
219	  if (overall_state == MlirOptimizationPassState::Disabled) {
220	    if (VLOG_IS_ON(1)) {
221	      LOG_FIRST_N(INFO, 1)
222	          << "None of the MLIR Optimization Passes are enabled "
223	          << "(registered " << registry_->passes().size() << ")";
224	    }
225	    return absl::OkStatus();
226	  }
227	
228	  if (VLOG_IS_ON(1)) {
229	    LOG_FIRST_N(INFO, 1) << "MLIR Graph Optimization Passes."
230	                         << " Enabled: " << num_passes_enabled
231	                         << ", Disabled: " << num_passes_disabled
232	                         << ", FallbackEnabled: " << num_passes_fallback_enabled
233	                         << ", Total: " << registry_->passes().size();
234	  }
235	
236	  GraphDebugInfo debug_info;
237	  mlir::DialectRegistry registry;
238	  RegisterDialects(registry);
239	  mlir::MLIRContext context(registry);
240	  GraphImportConfig import_config;
241	  import_config.graph_as_function = true;
242	  import_config.control_outputs = *control_ret_node_names;
243	  import_config.upgrade_legacy = true;
244	  // Disable shape inference during import as some TensorFlow op fails during
245	  // shape inference with dynamic shaped operands. This in turn causes the
246	  // import to fail. Shape inference during import is going to be removed and
247	  // the shape inference pass is run early in the pass pipeline, shape inference
248	  // during import is not necessary.
249	  import_config.enable_shape_inference = false;
250	  import_config.xla_compile_device_type =
251	      function_options.xla_compile_device_type;
252	  import_config.enable_soft_placement = function_options.allow_soft_placement;
253	
254	  static const char* kTfMlirCategory = "TfMlir";
255	  tensorflow::metrics::ScopedCounter<2> timings(
256	      tensorflow::metrics::GetGraphOptimizationCounter(),
257	      {kTfMlirCategory, "convert_graph_to_mlir"});
258	
259	  auto module_ref_status = tensorflow::tf2xla::v2::ConvertGraphToTfExecutor(
260	      **graph, debug_info, *flib_def, import_config, &context,
261	      /*tf_name_to_mlir_name*/ nullptr, config_proto,
262	      tensorflow::TF2XLABridgeVersion::kNominal);
263	  mlir_function_pass_graph_conversion_count
264	      ->GetCell(absl::StatusCodeToString(module_ref_status.status().code()))
265	      ->IncrementBy(1);
266	  timings.ReportAndStop();
267	
268	  if (!module_ref_status.ok()) {
269	    // If at least one pass is enabled, return failure to the caller
270	    // immediately.
271	    if (overall_state == MlirOptimizationPassState::Enabled) {
272	      return module_ref_status.status();
273	    }
274	    // Do not fail, just keep the original TF graph unchanged in fallback mode.
275	    LOG(WARNING) << "Failed to convert graph to MLIR: "
276	                 << module_ref_status.status()
277	                 << " , continuing without MlirOptimizationPass because "
278	                    "fallback enabled.";
279	    return absl::OkStatus();
280	  }
281	
282	  mlir::OwningOpRef<mlir::ModuleOp> module_ref =
283	      std::move(module_ref_status.value());
284	  AddDevicesToOp(*module_ref, &device_set);
285	
286	  int per_pass_state_index = 0;
287	  bool is_module_updated = false;
288	  for (auto& pass_registration : registry_->passes()) {
289	    llvm::StringRef name = pass_registration.pass->name();
290	
291	    if (DEBUG_DATA_DUMPER()->ShouldDump(function_name, kDebugGroupMain) ||
292	        VLOG_IS_ON(1)) {
293	      ::tensorflow::DumpMlirOpToFile(
294	          DEBUG_DATA_DUMPER()->GetDumpFilename(
295	              function_name, kDebugGroupMain,
296	              llvm::formatv("mlir_{0}_before", name)),
297	          *module_ref, llvm::StringRef(), nullptr);
298	    }
299	
300	    absl::Status pass_status = absl::OkStatus();
301	    auto pass_state = per_pass_state[per_pass_state_index++];
302	    if (pass_state == MlirOptimizationPassState::Enabled) {
303	      VLOG(2) << "Run MLIR graph optimization pass: " << StringRefToView(name);
304	      VLOG(2) << "Graph #nodes " << (*graph)->num_nodes() << " #edges "
305	              << (*graph)->num_edges();
306	      timings.Reset({kTfMlirCategory, name.str()});
307	      pass_status = pass_registration.pass->Run(
308	          function_name, config_proto, *module_ref, **graph, *flib_def);
309	      timings.ReportAndStop();
310	      if (pass_status.ok()) {
311	        VLOG(2) << "Finished MLIR graph optimization pass: "
312	                << StringRefToView(name);
313	        VLOG(2) << "Graph #nodes " << (*graph)->num_nodes() << " #edges "
314	                << (*graph)->num_edges();
315	        is_module_updated = true;
316	      }
317	    } else if (pass_state == MlirOptimizationPassState::FallbackEnabled) {
318	      VLOG(2) << "Run MLIR graph optimization pass with fallback: "
319	              << StringRefToView(name);
320	      VLOG(2) << "Graph #nodes " << (*graph)->num_nodes() << " #edges "
321	              << (*graph)->num_edges();
322	      // Make sure when the pass is FallbackEnabled, it only modifies the MLIR
323	      // module in case of no failures.
324	      auto module_ref_clone = module_ref->clone();
325	      timings.Reset({kTfMlirCategory, name.str() + "_fallback"});
326	      pass_status = pass_registration.pass->Run(
327	          function_name, config_proto, module_ref_clone, **graph, *flib_def);
328	      timings.ReportAndStop();
329	
330	      if (pass_status.ok()) {
331	        VLOG(2) << "Finished MLIR graph optimization pass with fallback: "
332	                << StringRefToView(name);
333	        VLOG(2) << "Graph #nodes " << (*graph)->num_nodes() << " #edges "
334	                << (*graph)->num_edges();
335	        module_ref = module_ref_clone;
336	        is_module_updated = true;
337	      } else {
338	        module_ref_clone->destroy();
339	      }
340	    } else {
341	      VLOG(2) << "MLIR graph optimization pass: " << StringRefToView(name)
342	              << " is disabled and will not be run.";
343	    }
344	
345	    if (!pass_status.ok()) {
346	      // If pass failed and it is:
347	      //   FallbackEnabled - only collect metrics, do not propagate
348	      //     error to the caller.
349	      //   Enabled - return error back to the caller.
350	      if (pass_state == MlirOptimizationPassState::FallbackEnabled) {
351	        LOG(WARNING)
352	            << StringRefToView(name)
353	            << " pass failed, continuing without the pass because the "
354	            << "pass has fallback enabled. This was the pass failure:\n"
355	            << pass_status;
356	        mlir_function_pass_fallback_count->GetCell(kFailure)->IncrementBy(1);
357	      } else if (pass_state == MlirOptimizationPassState::Enabled) {
358	        return pass_status;
359	      }
360	    } else {
361	      if (pass_state == MlirOptimizationPassState::FallbackEnabled) {
362	        mlir_function_pass_fallback_count->GetCell(kSuccess)->IncrementBy(1);
363	      }
364	    }
365	
366	    if (DEBUG_DATA_DUMPER()->ShouldDump(function_name, kDebugGroupMain) ||
367	        VLOG_IS_ON(1)) {
368	      ::tensorflow::DumpMlirOpToFile(DEBUG_DATA_DUMPER()->GetDumpFilename(
369	                                         function_name, kDebugGroupMain,
370	                                         llvm::formatv("mlir_{0}_after", name)),
371	                                     *module_ref, llvm::StringRef(), nullptr);
372	    }
373	  }
374	
375	  if (!is_module_updated) {
376	    VLOG(2) << "MLIR module is not updated. Using the original graph. "
377	            << "Do not convert mlir module back to graph";
378	    return absl::OkStatus();
379	  }
380	  GraphExportConfig export_config;
381	  absl::flat_hash_set<Node*> control_ret_nodes;
382	
383	  timings.Reset({kTfMlirCategory, "convert_mlir_to_graph"});
384	  // Some or all passes are enabled. Convert MLIR module and return back
385	  // resulted graph.
386	  absl::Status status = tensorflow::tf2xla::v2::ConvertTfExecutorToGraph(
387	      *module_ref, export_config, graph, flib_def, &control_ret_nodes);
388	  if (!status.ok()) {
389	    errors::AppendToMessage(&status,
390	                            "Error converting MLIR module back to graph");
391	    return status;
392	  }
393	
394	  timings.ReportAndStop();
395	
396	  control_ret_node_names->clear();
397	  control_ret_node_names->reserve(control_ret_nodes.size());
398	  for (const auto* node : control_ret_nodes)
399	    control_ret_node_names->push_back(node->name());
400	
401	  *control_rets_updated = true;
402	
403	  return absl::OkStatus();
404	}
405	
406	MlirV1CompatOptimizationPassRegistry&
407	MlirV1CompatOptimizationPassRegistry::Global() {
408	  static auto* global = new MlirV1CompatOptimizationPassRegistry();
409	  return *global;
410	}
411	
412	absl::Status MlirV1CompatGraphOptimizationPass::Run(
413	    const GraphOptimizationPassOptions& options) {
414	  // Skip MLIR V1 optimization pass if it is not enabled in compiling
415	  // SavedModel.
416	  if (!options.enable_tf2xla_mlir_bridge) {
417	    LOG(INFO)
418	        << "MLIR V1 optimization pass is not enabled in compiling SavedModel.";
419	    metrics::UpdateTfMlirBridgeFirstPhaseCounter(
420	        /*bridge_type*/ mlir::TF::kMlirPh1BridgeCounterReplicated,
421	        /*bridge_version*/ mlir::TF::kMlirPh1BridgeCounterV1,
422	        /*device_type*/ mlir::TF::kMlirPh1BridgeCounterTpu,
423	        /*fallback_enabled*/ true,
424	        /*result*/ "disabled_by_user");
425	    return absl::OkStatus();
426	  }
427	  // Skip function graphs as MlirOptimizationPassRegistry_ will be used instead.
428	  // Skip if no underlying pass was registered.
429	  if (options.is_function_graph || !registry_->pass()) return absl::OkStatus();
430	
431	  auto pass = registry_->pass();
432	  auto pass_state =
433	      pass->GetPassState(options.device_set, options.session_options->config,
434	                         **options.graph, *options.flib_def);
435	
436	  if (pass_state == MlirOptimizationPassState::Disabled) {
437	    LOG_FIRST_N(INFO, 1) << "MLIR V1 optimization pass is not enabled";
438	    return absl::OkStatus();
439	  }
440	
441	  LOG_FIRST_N(INFO, 1) << "Running MLIR Graph Optimization V1 Compat Pass";
442	
443	  GraphDebugInfo debug_info;
444	  mlir::DialectRegistry registry;
445	  RegisterDialects(registry);
446	  mlir::MLIRContext context(registry);
447	  GraphImportConfig import_config;
448	  import_config.upgrade_legacy = true;
449	  // Restrict functionalization to compiled nodes to avoid problems in v1
450	  // session runtime.
451	  import_config.restrict_functionalization_to_compiled_nodes = true;
452	
453	  std::string model_name =
454	      options.session_options->config.experimental().session_metadata().name();
455	
456	  auto module_ref_status = tensorflow::tf2xla::v2::ConvertGraphToTfExecutor(
457	      **options.graph, debug_info, *options.flib_def, import_config, &context,
458	      /*tf_name_to_mlir_name*/ nullptr, options.session_options->config,
459	      tensorflow::TF2XLABridgeVersion::kV1Compat);
460	  mlir_v1_compat_graph_conversion_count
461	      ->GetCell(absl::StatusCodeToString(module_ref_status.status().code()))
462	      ->IncrementBy(1);
463	
464	  if (!module_ref_status.ok()) {
465	    mlir_v1_compat_graph_conversion_failure_model_name_count
466	        ->GetCell(model_name)
467	        ->IncrementBy(1);
468	  }
469	
470	  if (!module_ref_status.ok()) {
471	    if (pass_state == MlirOptimizationPassState::Enabled) {
472	      return module_ref_status.status();
473	    }
474	    LOG(WARNING) << "Failed to convert graph to MLIR: "
475	                 << module_ref_status.status()
476	                 << " , continuing without MlirOptimizationPass because "
477	                    "fallback enabled.";
478	    return absl::OkStatus();
479	  }
480	
481	  mlir::OwningOpRef<mlir::ModuleOp> module_ref =
482	      std::move(module_ref_status.value());
483	  AddDevicesToOp(*module_ref, options.device_set);
484	
485	  auto module_ref_clone = module_ref->clone();
486	  llvm::StringRef name = pass->name();
487	  VLOG(2) << "Run MLIR V1 graph optimization pass: " << StringRefToView(name);
488	
489	  if (VLOG_IS_ON(1)) {
490	    DumpModule(*module_ref, llvm::formatv("mlir_{0}_before_", name));
491	  }
492	  absl::Status pass_status = pass->Run(options, *module_ref);
493	
494	  bool is_module_updated = !mlir::OperationEquivalence::isEquivalentTo(
495	      module_ref_clone, *module_ref,
496	      mlir::OperationEquivalence::Flags::IgnoreLocations);
497	  // Destroy this cloned op to avoid memory leaks.
498	  module_ref_clone->destroy();
499	
500	  if (!pass_status.ok()) {
501	    if (pass_state == MlirOptimizationPassState::Enabled) return pass_status;
502	
503	    if (pass_state == MlirOptimizationPassState::FallbackEnabled) {
504	      LOG(WARNING) << StringRefToView(name)
505	                   << " pass failed, continuing without the pass because the "
506	                      "pass has fallback enabled";
507	      mlir_graph_optimization_pass_fallback_count->GetCell(kFailure)
508	          ->IncrementBy(1);
509	      return absl::OkStatus();
510	    }
511	  } else {
512	    if (pass_state == MlirOptimizationPassState::FallbackEnabled) {
513	      mlir_graph_optimization_pass_fallback_count->GetCell(kSuccess)
514	          ->IncrementBy(1);
515	    }
516	  }
517	
518	  if (VLOG_IS_ON(1)) {
519	    DumpModule(*module_ref, llvm::formatv("mlir_{0}_after_", name));
520	  }
521	
522	  if (!is_module_updated) {
523	    VLOG(2) << "MLIR module is not updated. Using the original graph. "
524	            << "Do not convert mlir module back to graph";
525	    return absl::OkStatus();
526	  }
527	
528	  GraphExportConfig export_config;
529	  absl::flat_hash_set<Node*> control_ret_nodes;
530	  TF_RETURN_WITH_CONTEXT_IF_ERROR(
531	      tensorflow::tf2xla::v2::ConvertTfExecutorToGraph(
532	          *module_ref, export_config, options.graph, options.flib_def,
533	          &control_ret_nodes),
534	      "Error converting MLIR module back to graph");
535	
536	  return absl::OkStatus();
537	}
538	
539	}  // namespace tensorflow
