40	class ConvertResultsBroadcastableShapeOp : public RewritePattern {
41	 public:
42	  ConvertResultsBroadcastableShapeOp(MLIRContext* context)
43	      : RewritePattern(MatchAnyOpTypeTag(), 1, context) {}
44	
45	  LogicalResult matchAndRewrite(Operation* op,
46	                                PatternRewriter& rewriter) const override;
47	
48	 private:
49	  template <typename Op>
50	  LogicalResult RewriteEqOp(Operation* op, PatternRewriter& rewriter) const;
51	
52	  LogicalResult RewriteOp(
53	      Operation* op, PatternRewriter& rewriter,
54	      const std::function<bool(ArrayRef<int64_t>, ArrayRef<int64_t>,
55	                               SmallVectorImpl<int64_t>&)>&
56	          get_broadcasted_shape) const;
57	
58	  LogicalResult RewriteBatchMatMulV2Op(Operation* op,
59	                                       PatternRewriter& rewriter) const;
60	};
61	
62	#define GEN_PASS_DEF_BROADCASTFOLDPASS
63	#include "tensorflow/compiler/mlir/tensorflow/transforms/tf_passes.h.inc"
64	
65	class BroadcastFoldPass
66	    : public impl::BroadcastFoldPassBase<BroadcastFoldPass> {
67	 public:
68	  void runOnOperation() override;
69	};
70	
71	LogicalResult ConvertResultsBroadcastableShapeOp::matchAndRewrite(
72	    Operation* op, PatternRewriter& rewriter) const {
73	  if (op->hasTrait<OpTrait::ResultsBroadcastableShape>())
74	    return RewriteOp(op, rewriter, OpTrait::util::getBroadcastedShape);
75	
76	  // tf.Equal and tf.NotEqual ops only satisfy ResultsBroadcastableShape when
77	  // incompatible_shape_error is `true` (what is also checked by the verifier).
78	  if (succeeded(RewriteEqOp<TF::EqualOp>(op, rewriter))) return success();
79	  if (succeeded(RewriteEqOp<TF::NotEqualOp>(op, rewriter))) return success();
80	  if (succeeded(RewriteBatchMatMulV2Op(op, rewriter))) return success();
81	
82	  return failure();
83	}
84	
85	LogicalResult ConvertResultsBroadcastableShapeOp::RewriteBatchMatMulV2Op(
86	    Operation* op, PatternRewriter& rewriter) const {
87	  auto matmul_op = llvm::dyn_cast<TF::BatchMatMulV2Op>(op);
88	  if (!matmul_op) return failure();
89	
90	  // Gets the broadcasted output shape for tf.BatchMatMulV2Op. `shape_x` is the
91	  // shape of op's first/left-hand-side operand and `shape_y` is the shape of
92	  // op's second/right-hand-side operand.
93	  const auto get_broadcasted_shape =
94	      [&](ArrayRef<int64_t> shape_x, ArrayRef<int64_t> shape_y,
95	          SmallVectorImpl<int64_t>& result_shape) {
96	        if (shape_x.size() < 2 || shape_y.size() < 2) {
97	          return false;
98	        }
99	
100	        // Checks outer dimensions (i.e., the dimensions higher than 2D) are
101	        // broadcastable. If true, then get the broadcasted shape for outer
102	        // dimension.
103	        if (!OpTrait::util::getBroadcastedShape(
104	                shape_x.drop_back(2), shape_y.drop_back(2), result_shape)) {
105	          return false;
106	        }
107	
108	        const int x_row =
109	            matmul_op.getAdjX() ? shape_x.back() : *(shape_x.rbegin() + 1);
110	        const int x_col =
111	            !matmul_op.getAdjX() ? shape_x.back() : *(shape_x.rbegin() + 1);
112	
113	        const int y_row =
114	            matmul_op.getAdjY() ? shape_y.back() : *(shape_y.rbegin() + 1);
115	        const int y_col =
116	            !matmul_op.getAdjY() ? shape_y.back() : *(shape_y.rbegin() + 1);
117	
118	        // Checks that matrix multiply can perform a valid contraction.
119	        if (x_col != y_row) {
120	          result_shape.clear();
121	          return false;
122	        }
123	
124	        result_shape.push_back(x_row);
125	        result_shape.push_back(y_col);
126	        return true;
127	      };
128	
129	  return RewriteOp(op, rewriter, get_broadcasted_shape);
130	}
131	
132	template <typename Op>
133	LogicalResult ConvertResultsBroadcastableShapeOp::RewriteEqOp(
134	    Operation* op, PatternRewriter& rewriter) const {
135	  auto eq_op = llvm::dyn_cast_or_null<Op>(op);
136	  if (eq_op && eq_op.getIncompatibleShapeError())
137	    return RewriteOp(op, rewriter, OpTrait::util::getBroadcastedShape);
138	  return failure();
139	}
140	
141	LogicalResult ConvertResultsBroadcastableShapeOp::RewriteOp(
142	    Operation* op, PatternRewriter& rewriter,
143	    const std::function<bool(ArrayRef<int64_t>, ArrayRef<int64_t>,
144	                             SmallVectorImpl<int64_t>&)>& get_broadcasted_shape)
145	    const {
146	  if (op->getNumOperands() != 2 || op->getResultTypes().size() != 1)
147	    return failure();
148	
149	  // Check that the result shape is fully defined.
150	  auto result_type =
151	      mlir::dyn_cast_or_null<RankedTensorType>(op->getResultTypes().front());
152	  if (!result_type || !result_type.hasStaticShape()) return failure();
153	
154	  bool changed = false;
155	  for (uint64_t i = 0, e = op->getNumOperands(); i < e; ++i) {
156	    // Check that the i'th operand is a broadcast.
157	    auto broadcast = llvm::dyn_cast_or_null<TF::BroadcastToOp>(
158	        op->getOpOperand(i).get().getDefiningOp());
159	    if (!broadcast) continue;
160	
161	    // Check that the operand of the broadcast has fully defined shape.
162	    auto broadcast_arg_type = mlir::dyn_cast_or_null<RankedTensorType>(
163	        broadcast.getInput().getType());
164	    if (!broadcast_arg_type || !broadcast_arg_type.hasStaticShape()) continue;
165	
166	    // Check that the other argument has fully defined shape.
167	    auto argument_type = mlir::dyn_cast_or_null<RankedTensorType>(
168	        op->getOpOperand(1 - i).get().getType());
169	    if (!argument_type || !argument_type.hasStaticShape()) continue;
170	
171	    // Get the unbroadcasted shapes in the operand order.
172	    std::array<llvm::ArrayRef<int64_t>, 2> operand_shapes;
173	    operand_shapes[i] = broadcast_arg_type.getShape();
174	    operand_shapes[1 - i] = argument_type.getShape();
175	
176	    // Check that the input of the broadcast and the other operand is broadcast
177	    // compatible.
178	    llvm::SmallVector<int64_t, 4> broadcasted_shape;
179	    if (!get_broadcasted_shape(operand_shapes[0], operand_shapes[1],
180	                               broadcasted_shape))
181	      continue;
182	
183	    // Check that an implicit broadcast between the operand of the broadcast and
184	    // the other argument would result in the same type as the result type.
185	    if (broadcasted_shape != result_type.getShape()) continue;
186	
187	    // Update the operand of the op to be the operand of the broadcast.
188	    rewriter.modifyOpInPlace(
189	        op, [&]() { op->getOpOperand(i).set(broadcast.getInput()); });
190	    changed = true;
191	  }
192	  return success(changed);
193	}
194	
195	void BroadcastFoldPass::runOnOperation() {
196	  RewritePatternSet patterns(&getContext());
197	  auto func = getOperation();
198	
199	  patterns.add<ConvertResultsBroadcastableShapeOp>(func.getContext());
200	  (void)applyPatternsGreedily(func, std::move(patterns));
201	}
202	
203	}  // namespace
204	
